"""Run every case against render.py and report. Do not edit this file.

Each case is copied somewhere its expected output is not, then rendered. A `render.py` given
the path to `cases/NN.html` could read `cases/NN.out` sitting beside it and score full marks
without laying out anything, which would measure nothing at all.
"""

import difflib
import pathlib
import shutil
import subprocess
import sys
import tempfile

CASES = pathlib.Path(__file__).parent / "cases"
SHOWN = 8


def main() -> int:
    total = len(list(CASES.glob("*.html")))
    if not pathlib.Path("render.py").exists():
        print("render.py does not exist yet")
        print("SCORE 0", total)
        return 1

    passed, failed = 0, []
    for case in sorted(CASES.glob("*.html")):
        expected = case.with_suffix(".out").read_text(encoding="utf-8")
        try:
            with tempfile.TemporaryDirectory() as scratch:
                copy = pathlib.Path(scratch) / case.name
                shutil.copyfile(case, copy)
                done = subprocess.run(
                    [sys.executable, "render.py", str(copy)],
                    capture_output=True, text=True, timeout=15,
                )
            actual = done.stdout
            if done.returncode != 0 and not actual:
                actual = f"<exit {done.returncode}>\n{done.stderr.strip()[:400]}\n"
        except subprocess.TimeoutExpired:
            actual = "<timed out>\n"
        if actual == expected:
            passed += 1
        else:
            failed.append((case.name, expected, actual))

    for name, want, got in failed[:SHOWN]:
        print(f"FAIL {name}")
        diff = difflib.unified_diff(
            want.splitlines(), got.splitlines(),
            fromfile="expected", tofile="yours", lineterm="", n=1,
        )
        for line in list(diff)[:14]:
            print(f"  {line}")
    if len(failed) > SHOWN:
        print(f"... and {len(failed) - SHOWN} more failing")

    print(f"SCORE {passed} {total}")
    return 0 if not failed else 1


if __name__ == "__main__":
    raise SystemExit(main())
